package com.automark.connector;
import com.automark.domain.FactType; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import org.springframework.stereotype.Component; import java.time.*; import java.util.*;
@Component public class RdwFactNormalizer implements FactNormalizer {
 private final ObjectMapper mapper; public RdwFactNormalizer(ObjectMapper mapper){this.mapper=mapper;} public String sourceId(){return "RDW_NL";}
 public List<FactCandidate> normalize(JsonNode payload){ List<FactCandidate> result=new ArrayList<>(); for(JsonNode row:payload){ObjectNode spec=mapper.createObjectNode(); copy(row,spec,"merk","make");copy(row,spec,"handelsbenaming","model");copy(row,spec,"datum_eerste_toelating","firstRegistration");copy(row,spec,"brandstof_omschrijving","fuel");copy(row,spec,"inrichting","bodyType"); result.add(new FactCandidate(FactType.VEHICLE_SPECIFICATION,spec,parseDate(row.path("datum_eerste_toelating").asText()),.95)); if(row.hasNonNull("datum_tenaamstelling")){ObjectNode registration=mapper.createObjectNode();registration.put("plate",row.path("kenteken").asText());registration.put("event","REGISTERED");result.add(new FactCandidate(FactType.REGISTRATION_EVENT,registration,parseDate(row.path("datum_tenaamstelling").asText()),.9));}} return result; }
 private void copy(JsonNode from,ObjectNode to,String fromKey,String toKey){if(from.hasNonNull(fromKey))to.put(toKey,from.get(fromKey).asText());} private Instant parseDate(String s){try{return LocalDate.parse(s).atStartOfDay(ZoneOffset.UTC).toInstant();}catch(Exception e){return null;}}
}
